// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data, address caller) public {
        vm.assume(caller != c.owner());
        vm.assume(caller != address(0));
        vm.assume(target != address(c));
        vm.deal(caller, value);
        vm.prank(caller);
        bool ok;
        try c.sendMoney(target, value, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
